import asyncio, json
from h import *
TODAY="new Date().toLocaleDateString('en-CA')"
async def add(pg,title,tm=None):
    await pg.fill('#wkIn',title)
    if tm: await pg.fill('#wkTm',tm)
    await pg.press('#wkIn','Enter'); await pg.wait_for_timeout(150)
